#include<bits/stdc++.h>using namespace std; int main(){    int t;    cin >> t;    while(t--)    {        int n=7;        vector<int> a(n);        for(int i=0;i<n;i++)        {            cin >> a[i];        }        int sum=0;        int maxa = *(max_element(a.begin(),a.end()));        bool found = true;        for(int i=0;i<n;i++)        {            if(a[i] == maxa && found)            {                sum += a[i];                found = false;            }            else            {                sum -=a[i];            }        }        cout << sum << endl;    }}